examples.code:
slice();
slice(start);
slice(start, end);

let arr = [1, 2, 3, 4, 5, 6];
console.log(arr.slice()); // [1,2,3,4,5,6]
// slice(start)
arr.slice(2); // [3,4,5,6]
let arr2 = arr.slice(2);
console.log(arr2, arr); // [3,4,5,6] [1,2,3,4,5,6]
// slice(start, end) end must be greater than start
let arr2 = arr.slice(2, 4);
console.log(arr2, arr); // [3,4] [1,2,3,4,5,6]

const animals = ["ant", "bison", "camel", "duck", "elephant"];
console.log(animals.slice()); // ["ant", "bison", "camel", "duck", "elephant"]
console.log(animals.slice(2)); // ["camel", "duck", "elephant"]
console.log(animals.slice(-2)); // ["duck", "elephant"]
console.log(animals.slice(2, 4)); // ["camel", "duck"]
console.log(animals.slice(1, 5)); // ["bison", "camel", "duck", "elephant"]
console.log(animals.slice(2, -1)); // ["camel", "duck"]

// Example with objects:
let myHonda = { color: "red", wheels: 4, engine: { cylinders: 4, size: 2.2 } };
let myCar = [myHonda, 2, "cherry condition", "purchased 1997"];
let newCar = myCar.slice(0, 3);
console.log(newCar);
// [{ color: 'red', wheels: 4, engine: { cylinders: 4, size: 2.2 } }, 2, "cherry condition"]

sections.content:
**<ins>Trả về bản sao nông của một phần mảng</ins>** vào một đối tượng mảng mới được chọn từ `start` đến `end` (`end` không bao gồm) trong đó `start` và `end` đại diện cho chỉ số của các phần tử trong mảng đó, không làm thay đổi mảng. Có thể dùng trên chuỗi.

Cú pháp MDN:

```js
slice();
slice(start);
slice(start, end);

let arr = [1, 2, 3, 4, 5, 6];
console.log(arr.slice()); // [1,2,3,4,5,6]
// slice(start)
arr.slice(2); // [3,4,5,6]
let arr2 = arr.slice(2);
console.log(arr2, arr); // [3,4,5,6] [1,2,3,4,5,6]
// slice(start, end) end must be greater than start
let arr2 = arr.slice(2, 4);
console.log(arr2, arr); // [3,4] [1,2,3,4,5,6]
```

<br />

Ví dụ:

```js
const animals = ["ant", "bison", "camel", "duck", "elephant"];
console.log(animals.slice()); // ["ant", "bison", "camel", "duck", "elephant"]
console.log(animals.slice(2)); // ["camel", "duck", "elephant"]
console.log(animals.slice(-2)); // ["duck", "elephant"]
console.log(animals.slice(2, 4)); // ["camel", "duck"]
console.log(animals.slice(1, 5)); // ["bison", "camel", "duck", "elephant"]
console.log(animals.slice(2, -1)); // ["camel", "duck"]

// Example with objects:
let myHonda = { color: "red", wheels: 4, engine: { cylinders: 4, size: 2.2 } };
let myCar = [myHonda, 2, "cherry condition", "purchased 1997"];
let newCar = myCar.slice(0, 3);
console.log(newCar);
// [{ color: 'red', wheels: 4, engine: { cylinders: 4, size: 2.2 } }, 2, "cherry condition"]
```

